create table if not exists rental_contractor_payments(owner_id text not null,id text not null,contractor_id text not null,work_order_id text,property_id text not null,paid_at date not null,amount_cents bigint not null check(amount_cents>0),payment_method text not null,reference text,invoice_reference text,invoice_document_id text,notes text,tax_year smallint generated always as(extract(year from paid_at))stored,created_at timestamptz not null default now(),primary key(owner_id,id),foreign key(owner_id,contractor_id)references rental_contractors(owner_id,id),foreign key(owner_id,work_order_id)references rental_maintenance_work_orders(owner_id,id),foreign key(owner_id,invoice_document_id)references rental_documents(owner_id,id));
create index if not exists rental_contractor_payments_tax_year on rental_contractor_payments(owner_id,tax_year,contractor_id);
alter table rental_contractor_payments enable row level security;alter table rental_contractor_payments force row level security;create policy rental_contractor_payment_owner_all on rental_contractor_payments for all to authenticated using(owner_id=auth.uid()::text)with check(owner_id=auth.uid()::text);
create table if not exists rental_1099_reviews(owner_id text not null,id text not null,contractor_id text not null,tax_year smallint not null,status text not null default 'needs_review'check(status in('needs_review','accountant_reviewed','filing_required','not_required','prepared','filed','corrected')),accountant_note text,reviewed_at timestamptz,prepared_at timestamptz,filed_at timestamptz,filing_reference text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(owner_id,id),unique(owner_id,contractor_id,tax_year),foreign key(owner_id,contractor_id)references rental_contractors(owner_id,id));
alter table rental_1099_reviews enable row level security;alter table rental_1099_reviews force row level security;create policy rental_1099_review_owner_all on rental_1099_reviews for all to authenticated using(owner_id=auth.uid()::text)with check(owner_id=auth.uid()::text);
create or replace function record_rental_contractor_payment(p_owner_id text,p_contractor_id text,p_work_order_id text,p_property_id text,p_paid_at date,p_amount_cents bigint,p_payment_method text,p_reference text,p_invoice_reference text,p_invoice_document_id text,p_notes text)returns rental_contractor_payments language plpgsql security invoker set search_path=public as $$declare result rental_contractor_payments;begin if p_owner_id<>auth.uid()::text then raise exception 'Owner identity mismatch.';end if;if p_amount_cents<=0 or not exists(select 1 from rental_contractors where owner_id=p_owner_id and id=p_contractor_id)then raise exception 'Valid contractor payment is required.';end if;insert into rental_contractor_payments(owner_id,id,contractor_id,work_order_id,property_id,paid_at,amount_cents,payment_method,reference,invoice_reference,invoice_document_id,notes)values(p_owner_id,'rental_contractor_payment_'||gen_random_uuid()::text,p_contractor_id,p_work_order_id,p_property_id,p_paid_at,p_amount_cents,btrim(p_payment_method),nullif(btrim(p_reference),''),nullif(btrim(p_invoice_reference),''),p_invoice_document_id,nullif(btrim(p_notes),''))returning * into result;insert into rental_1099_reviews(owner_id,id,contractor_id,tax_year)values(p_owner_id,'rental_1099_review_'||gen_random_uuid()::text,p_contractor_id,extract(year from p_paid_at)::smallint)on conflict(owner_id,contractor_id,tax_year)do nothing;return result;end$$;
grant execute on function record_rental_contractor_payment(text,text,text,text,date,bigint,text,text,text,text,text)to authenticated;
